# DISCLAMER: This file is generated by AI for testing purposes.
import json
import os
import tempfile
import unittest
from pathlib import Path

from iSpy.config.iSpyConfig import iSpyConfig
from iSpy.web.Backend.PluginStatus import _coerce_setting_value
from iSpy.web.Backend.WebApp import create_app


def _config_file(tmp: str, *, pipeline="hsv_detection") -> str:
    path = Path(tmp) / "config.json"
    path.write_text(
        json.dumps(
            {
                "admin": True,
                "camera_configs": {
                    "cam": {
                        "name": "cam",
                        "camera_type": "opencv",
                        "source": 0,
                        "pipeline": {"name": pipeline, "settings": {}},
                    }
                },
                "plugins": {
                    "trackers": {},
                    "utilities": {},
                    "frame_processors": {},
                },
            }
        )
    )
    return str(path)


def _client(path: str):
    config = iSpyConfig(file_path=path, create=False)
    return config, create_app(cameras=[], config=config).flask_app.test_client()


class EditorApiTests(unittest.TestCase):
    def test_editor_page_is_additive(self):
        with tempfile.TemporaryDirectory() as tmp:
            _config, client = _client(_config_file(tmp))
            response = client.get("/editor")
            self.assertEqual(response.status_code, 200)
            self.assertIn(b"Pipeline Editor", response.data)

    def test_palette_reuses_existing_global_plugin_settings(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = _config_file(tmp)
            config, client = _client(path)
            config.config["plugins"]["trackers"]["FRC/object_tracker"] = {
                "distance_threshold": 0.77
            }
            data = client.get("/api/editor/graph").get_json()
            tracker = next(
                item
                for item in data["palette"]["trackers"]
                if item["name"] == "FRC/object_tracker"
            )
            self.assertEqual(tracker["defaults"]["distance_threshold"], 0.77)
            self.assertFalse(data["graph"]["layout_saved"])

            graph = data["graph"]
            response = client.post(
                "/api/editor/graph",
                json={"nodes": graph["nodes"], "edges": graph["edges"]},
            )
            self.assertEqual(response.status_code, 200, response.get_json())
            self.assertTrue(response.get_json()["graph"]["layout_saved"])

    def test_graph_contains_real_schemas_and_required_metadata(self):
        with tempfile.TemporaryDirectory() as tmp:
            _config, client = _client(_config_file(tmp, pipeline="object_detection"))
            response = client.get("/api/editor/graph")
            self.assertEqual(response.status_code, 200)
            data = response.get_json()
            self.assertTrue(data["ok"])
            nodes = {node["id"]: node for node in data["graph"]["nodes"]}
            camera = nodes["camera:cam"]
            pipeline = nodes["pipeline:cam"]
            self.assertEqual(camera["type"], "camera")
            self.assertIn("source", camera["schema"])
            self.assertEqual(pipeline["plugin"], "object_detection")
            self.assertIn("vision_model", pipeline["schema"])
            self.assertIn("vision_model", pipeline["required"])
            self.assertIn("vision_model", pipeline["completion"]["required"])
            self.assertEqual(data["palette"]["pipelines"][0]["type"], "pipeline")
            self.assertTrue(
                any(item["name"] == "FRC/object_tracker" for item in data["palette"]["trackers"])
            )

    def test_save_updates_camera_pipeline_and_global_order(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = _config_file(tmp)
            config, client = _client(path)
            graph = client.get("/api/editor/graph").get_json()["graph"]
            nodes = graph["nodes"]
            camera = next(node for node in nodes if node["id"] == "camera:cam")
            pipeline = next(node for node in nodes if node["id"] == "pipeline:cam")
            camera["settings"]["source"] = 2
            pipeline["settings"]["preset"] = "green"
            nodes.extend(
                [
                    {
                        "id": "tracker:example/example_tracker",
                        "type": "tracker",
                        "label": "Example tracker",
                        "plugin": "example/example_tracker",
                        "settings": {},
                    },
                    {
                        "id": "tracker:FRC/object_tracker",
                        "type": "tracker",
                        "label": "Object tracker",
                        "plugin": "FRC/object_tracker",
                        "settings": {"distance_threshold": 0.9},
                    },
                    {
                        "id": "utility:target_selector",
                        "type": "utility",
                        "label": "Target selector",
                        "plugin": "target_selector",
                        "settings": {},
                    },
                ]
            )
            response = client.post(
                "/api/editor/graph",
                json={"nodes": nodes, "layout": {"grid": 20, "viewport": {"zoom": 1}}},
            )
            self.assertEqual(response.status_code, 200, response.get_json())
            self.assertTrue(response.get_json()["restart_required"])
            saved = json.loads(Path(path).read_text())
            self.assertEqual(saved["camera_configs"]["cam"]["source"], 2)
            self.assertEqual(
                saved["camera_configs"]["cam"]["pipeline"]["settings"]["preset"],
                "green",
            )
            self.assertEqual(
                list(saved["plugins"]["trackers"]),
                ["example/example_tracker", "FRC/object_tracker"],
            )
            self.assertEqual(list(saved["plugins"]["utilities"]), ["target_selector"])
            self.assertEqual(saved["editor_graph"]["grid"], 20)

            reloaded = iSpyConfig(file_path=path, create=False)
            self.assertEqual(reloaded.config["camera_configs"]["cam"]["source"], 2)
            self.assertEqual(
                list(reloaded.config["plugins"]["trackers"]),
                ["example/example_tracker", "FRC/object_tracker"],
            )

    def test_invalid_connection_is_rejected_with_a_clear_error(self):
        with tempfile.TemporaryDirectory() as tmp:
            _config, client = _client(_config_file(tmp))
            graph = client.get("/api/editor/graph").get_json()["graph"]
            nodes = graph["nodes"]
            nodes.append(
                {
                    "id": "tracker:FRC/object_tracker",
                    "type": "tracker",
                    "label": "Object tracker",
                    "plugin": "FRC/object_tracker",
                    "settings": {},
                }
            )
            edges = list(graph["edges"])
            edges.append(
                {"from": "camera:cam", "to": "tracker:FRC/object_tracker"}
            )
            response = client.post(
                "/api/editor/validate",
                json={"nodes": nodes, "edges": edges},
            )
            self.assertEqual(response.status_code, 400)
            codes = {error["code"] for error in response.get_json()["errors"]}
            self.assertIn("edge_type", codes)

    def test_missing_required_model_is_rejected(self):
        with tempfile.TemporaryDirectory() as tmp:
            _config, client = _client(_config_file(tmp))
            graph = client.get("/api/editor/graph").get_json()["graph"]
            nodes = graph["nodes"]
            pipeline = next(node for node in nodes if node["type"] == "pipeline")
            pipeline["plugin"] = "object_detection"
            pipeline["settings"] = {"vision_model": ""}
            response = client.post("/api/editor/validate", json={"nodes": nodes})
            self.assertEqual(response.status_code, 400)
            errors = response.get_json()["errors"]
            self.assertTrue(any(error["code"] == "settings_incomplete" for error in errors))
            self.assertTrue(
                any("vision_model" in error.get("missing", []) for error in errors)
            )

    def test_duplicate_pipeline_is_rejected(self):
        with tempfile.TemporaryDirectory() as tmp:
            _config, client = _client(_config_file(tmp))
            graph = client.get("/api/editor/graph").get_json()["graph"]
            nodes = graph["nodes"]
            duplicate = dict(
                next(node for node in nodes if node["type"] == "pipeline")
            )
            duplicate["id"] = "pipeline:cam:duplicate"
            nodes.append(duplicate)
            response = client.post("/api/editor/validate", json={"nodes": nodes})
            self.assertEqual(response.status_code, 400)
            self.assertIn(
                "pipeline_duplicate",
                {error["code"] for error in response.get_json()["errors"]},
            )

    def test_remote_save_requires_admin_token(self):
        with tempfile.TemporaryDirectory() as tmp:
            _config, client = _client(_config_file(tmp))
            old = os.environ.pop("ISPY_ADMIN_TOKEN", None)
            try:
                response = client.post(
                    "/api/editor/graph",
                    json={"nodes": []},
                    environ_base={"REMOTE_ADDR": "10.1.2.3"},
                )
            finally:
                if old is not None:
                    os.environ["ISPY_ADMIN_TOKEN"] = old
            self.assertEqual(response.status_code, 403)


class NullableCoercionTests(unittest.TestCase):
    def test_nullable_empty_artifact_becomes_none(self):
        self.assertIsNone(
            _coerce_setting_value("", {"type": "browse", "nullable": True})
        )
        self.assertIsNone(
            _coerce_setting_value(None, {"type": "number", "nullable": True})
        )

    def test_non_nullable_empty_text_stays_a_string(self):
        self.assertEqual(
            _coerce_setting_value("", {"type": "text", "default": ""}), ""
        )


if __name__ == "__main__":
    unittest.main()
